const D = { scale:1, density:.7, energy:.72, speed:1, warp:.55, hue:172, x:.5, y:.5, style:'engraved', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const TAU = Math.PI * 2;
const wh = h => ((h % 360) + 360) % 360;
const u = Math.min(width, height);
const style = P.style;
const cx = width * P.x, cy = height * P.y;

// full-canvas buffer (crisp fine lines + clean alpha compositing) keyed on size
if (!S.buf || S.bkey !== width + 'x' + height) {
  S.buf = createGraphics(width, height);
  S.buf.colorMode(HSB, 360, 100, 100, 100);
  S.buf.pixelDensity(1);
  S.bkey = width + 'x' + height;
}
const g = S.buf;

// seed + density deterministic ring family (rebuild on seed OR ring-count change)
const M = Math.max(3, Math.round(4 + P.density * 8));
if (S.seedUsed !== P.seed || S.M !== M) {
  S.seedUsed = P.seed; S.M = M;
  const fr = i => { const s = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return s - Math.floor(s); };
  S.ring = [];
  for (let k = 0; k < M; k++) {
    S.ring.push({
      petals: 5 + Math.round(fr(k * 5 + 1) * 15),   // 5..20 lobes
      phase0: fr(k * 5 + 2) * TAU,
      ampMul: 0.6 + fr(k * 5 + 3) * 0.95,
      hoff: (fr(k * 5 + 4) - 0.5) * 60,
      dir: fr(k * 5 + 5) < 0.5 ? 1 : -1
    });
  }
  S.rm = 5 + Math.round(fr(900) * 8);               // central rosette harmonic 5..13
  S.rc = 0.34 + fr(901) * 0.46;                     // secondary amplitude ratio
  S.hoff2 = (fr(902) - 0.5) * 30;
}

// continuous motion — linear in K.t so it NEVER re-phases (guilloche precession)
const prec  = K.t * (0.014 + P.speed * 0.030) + 0.12 * Math.sin(K.t * 0.045);
const drift = K.t * (0.05 + P.speed * 0.07);
const rosPhi = K.t * (0.09 + P.speed * 0.09);
const sec = K.section;
const inten = 0.4 + K.intensity * 0.6;
const hb = wh(P.hue + S.hoff2 + sec * 14);
const eg = 0.6 + P.energy * 0.7;
const additive = (style === 'engraved' || style === 'neon' || style === 'iridescent');

g.clear();
g.blendMode(BLEND);
g.noFill();

// ground — native radial gradient (one GPU op, toned so the frame is never near-black)
let cin, cout;
if (style === 'engraved') { cin = '#123c50'; cout = '#03101c'; }     // deep petrol -> near-black
else if (style === 'currency') { cin = '#1d2a14'; cout = '#060a04'; } // dark security-print (reinterpreted bold)
else if (style === 'etch') { cin = '#f3efe5'; cout = '#d6d0c1'; }     // classic pale intaglio
else if (style === 'blueprint') { cin = '#12365f'; cout = '#071224'; }
else if (style === 'neon') { cin = '#0d0d24'; cout = '#040410'; }
else { cin = '#171129'; cout = '#05030c'; } // iridescent
const dc = g.drawingContext;
const grd = dc.createRadialGradient(cx, cy, u * 0.02, cx, cy, Math.hypot(width, height) * 0.62);
grd.addColorStop(0, cin); grd.addColorStop(1, cout);
dc.fillStyle = grd; dc.fillRect(0, 0, width, height);

// radii — outer reaches the corners so the lattice bleeds edge to edge
const half = Math.hypot(width, height) / 2;
const R0 = u * 0.05 * (0.5 + P.scale * 0.9);
const Rmax = half * (0.62 + P.scale * 0.5);
const spacing = (Rmax - R0) / M;
const waveBase = spacing * (0.3 + P.warp * 1.4);

if (additive) g.blendMode(ADD);

// ---- concentric guilloche rings (the security-print lattice) ----
const rpts = Math.max(90, Math.round(140 + P.density * 140));
for (let k = 0; k < M; k++) {
  const rg = S.ring[k];
  const base = R0 + spacing * k;
  let amp = waveBase * rg.ampMul * (0.72 + 0.42 * Math.sin(drift * rg.dir + k * 0.7));
  amp += A.lowmid * waveBase * 0.35;   // audio on top of the baseline
  amp *= inten;
  const ph = rg.phase0 + drift * rg.dir * (1 + 0.12 * k);
  const kfrac = k / (M - 1 || 1);
  if (style === 'engraved') { g.stroke(wh(hb + rg.hoff * 0.5 + k * 6), 80, 100, 46 * eg); g.strokeWeight(1.15); }
  else if (style === 'currency') { g.stroke(wh(hb + rg.hoff + 60), 74, 96, 60); g.strokeWeight(1.0); }
  else if (style === 'etch') { g.stroke(34, 10, 12, 88); g.strokeWeight(0.95); }
  else if (style === 'blueprint') { g.stroke(wh(200 + rg.hoff * 0.2), 55, 100, 56 + kfrac * 24); g.strokeWeight(1.05); }
  else if (style === 'neon') { g.stroke(wh(hb + k * 22 + prec * 30), 92, 100, 34 * eg); g.strokeWeight(1.25); }
  else { g.stroke(wh(hb + k * 36 + prec * 46), 72, 100, 32 * eg); g.strokeWeight(1.3); }
  g.beginShape();
  for (let i = 0; i <= rpts; i++) {
    const th = (i / rpts) * TAU;
    const r = base + amp * Math.sin(rg.petals * th + ph);
    const a = th + prec;
    g.vertex(cx + r * Math.cos(a), cy + r * Math.sin(a));
  }
  g.endShape();
}

// ---- central rosette (epitrochoid), nested copies — complementary interlace ----
const Rr = u * 0.24 * (0.4 + P.scale * 0.9);
const nCopies = 2 + Math.round(P.density * 2);
const cpts = Math.max(200, Math.round(300 + P.density * 260));
const b0 = S.rc * (1 + 0.16 * Math.sin(K.t * 0.3) + A.bass * 0.3);
for (let c = 0; c < nCopies; c++) {
  const scl = 1 - c * 0.12;
  const phiC = rosPhi + c * 0.5;
  const b = b0;
  if (style === 'engraved') { g.stroke(wh(hb + 172 + c * 26 + rosPhi * 24), 86, 100, 60 * eg); g.strokeWeight(1.4); }
  else if (style === 'currency') { g.stroke(wh(hb + S.hoff2 + 30), 80, 100, 80); g.strokeWeight(1.25); }
  else if (style === 'etch') { g.stroke(30, 12, 8, 92); g.strokeWeight(1.2); }
  else if (style === 'blueprint') { g.stroke(196, 32, 100, 88); g.strokeWeight(1.3); }
  else if (style === 'neon') { g.stroke(wh(hb + 44 + c * 20), 88, 100, 52 * eg); g.strokeWeight(1.4); }
  else { g.stroke(wh(hb + c * 44 + rosPhi * 40), 66, 100, 48 * eg); g.strokeWeight(1.4); }
  g.beginShape();
  for (let i = 0; i <= cpts; i++) {
    const th = (i / cpts) * TAU;
    const x = Rr * scl * (Math.cos(th) + b * Math.cos(S.rm * th + phiC)) / (1 + b);
    const y = Rr * scl * (Math.sin(th) - b * Math.sin(S.rm * th + phiC)) / (1 + b);
    const rx = x * Math.cos(prec) - y * Math.sin(prec);
    const ry = x * Math.sin(prec) + y * Math.cos(prec);
    g.vertex(cx + rx, cy + ry);
  }
  g.endShape();
}

g.blendMode(BLEND);

// ---- center ornament + pulsing rose-engine head ----
if (additive) g.blendMode(ADD);
g.noFill();
g.stroke(wh(hb + 30), (style === 'etch') ? 10 : 60, 100, 74);
g.strokeWeight(1.1);
g.ellipse(cx, cy, u * 0.028); g.ellipse(cx, cy, u * 0.05);
const hd = 3 + K.pulse * 4 + A.treble * 10;
g.noStroke();
if (style === 'etch') g.fill(28, 12, 12, 95);
else if (style === 'blueprint') g.fill(196, 22, 100, 95);
else g.fill(wh(hb + 20), 74, 100, 95);
if (style === 'engraved' || style === 'neon' || style === 'iridescent' || style === 'blueprint') {
  g.drawingContext.shadowBlur = 9 + A.rms * 22 + K.pulse * 6;
  g.drawingContext.shadowColor = 'rgba(180,235,255,0.75)';
}
g.ellipse(cx, cy, hd + 2);
g.drawingContext.shadowBlur = 0;
g.blendMode(BLEND);

// composite to main canvas (tint carries the alpha for VJ compositing; no bg clear)
push();
if (P.alpha < 100) tint(0, 0, 100, P.alpha);
image(g, 0, 0, width, height);
pop();
